const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  // Kandidat
  if (data.property_geburtsdatum) {
    let maxDistanz = 50;

    for (const key of Object.keys(data)) {
      if (key.toLowerCase().includes('gew') && key.toLowerCase().includes('nschte')) {
        const match = String(data[key]).match(/\d+/);
        if (match) {
          maxDistanz = parseInt(match[0]);
          break;
        }
      }
    }

    // Prüfe ob Koordinaten vorhanden sind
    const hasCoords = (data.property_latitude !== null && data.property_latitude !== undefined && 
                       data.property_longitude !== null && data.property_longitude !== undefined);

    results.push({
      json: {
        id: data.id,
        name: data.property_name,
        address: data.property_wohnadresse,
        lat: data.property_latitude,
        lng: data.property_longitude,
        max_distanz_km: maxDistanz,
        type: 'kandidat',
        needs_geocoding: !hasCoords
      }
    });
  }
  // Fachgeschäft
  else if (data.property_adresse) {
    const hasCoords = (data.property_latitude !== null && data.property_latitude !== undefined && 
                       data.property_longitude !== null && data.property_longitude !== undefined);

    results.push({
      json: {
        id: data.id,
        name: data.property_name,
        address: data.property_adresse,
        lat: data.property_latitude,
        lng: data.property_longitude,
        type: 'shop',
        needs_geocoding: !hasCoords
      }
    });
  }
}

return results;

const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const current = items[i].json;
  const original = $('Adressen extrahieren').all()[i].json;

  let finalLat = original.lat;
  let finalLng = original.lng;
  let needsSave = false;

  // Wenn Geocoding erfolgte und erfolgreich war
  if (original.needs_geocoding && current.status === 'OK' && current.results && current.results[0]) {
    const loc = current.results[0].geometry.location;
    finalLat = loc.lat;
    finalLng = loc.lng;
    needsSave = true;
  }

  results.push({
    json: {
      ...original,
      lat: finalLat,
      lng: finalLng,
      needs_save: needsSave
    }
  });
}

return results;

// Hole die ursprünglichen Daten von "Koordinaten zusammenführen"
const all = $('Koordinaten zusammenführen').all().map(x => x.json);
const kandidaten = all.filter(x => x.type === 'kandidat');
const shops = all.filter(x => x.type === 'shop');

// Hole Original-Notion-Daten
const kandidatenOriginal = $('Kandidaten laden').all().map(x => x.json);
const originalDataMap = {};
for (const k of kandidatenOriginal) {
  originalDataMap[k.id] = k;
}

function distance(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = (lat2-lat1) * Math.PI/180;
  const dLon = (lon2-lon1) * Math.PI/180;
  const a = Math.sin(dLat/2)**2 + Math.cos(lat1*Math.PI/180) * Math.cos(lat2*Math.PI/180) * Math.sin(dLon/2)**2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
}

const results = [];

for (const k of kandidaten) {
  const maxDist = Number(k.max_distanz_km);

  // Problem: Keine Koordinaten
  if (!k.lat || !k.lng) {
    results.push({
      json: {
        kandidat_name: k.name,
        kandidat_id: k.id,
        shop_ids: [],
        min_dist: null,
        status: '❌ Fehler',
        comment: '❌ Fehler: Keine Koordinaten verfügbar. Adresse konnte nicht geocoded werden.'
      }
    });
    continue;
  }

  // Problem: Keine gewünschte Distanz
  if (!maxDist || isNaN(maxDist)) {
    results.push({
      json: {
        kandidat_name: k.name,
        kandidat_id: k.id,
        shop_ids: [],
        min_dist: null,
        status: '❌ Fehler',
        comment: '❌ Fehler: Gewünschte Distanz nicht definiert.'
      }
    });
    continue;
  }

  const nearby = [];

  for (const s of shops) {
    if (!s.lat || !s.lng) continue;

    const d = distance(k.lat, k.lng, s.lat, s.lng);
    const distKm = Math.round(d*10)/10;

    if (d <= maxDist) {
      nearby.push({ id: s.id, name: s.name, dist: distKm });
    }
  }

  nearby.sort((a,b) => a.dist - b.dist);

  // Hole aktuelle Zuordnungen aus Notion
  const currentData = originalDataMap[k.id];
  const currentShopIds = (currentData && currentData.property_zuk_nftiger_arbeitgeber) 
    ? currentData.property_zuk_nftiger_arbeitgeber.map(rel => rel.id).sort() 
    : [];

  // Neue Shop IDs
  const newShopIds = nearby.map(x => x.id).sort();

  // Vergleiche: Nur updaten wenn sich etwas geändert hat
  const hasChanged = JSON.stringify(currentShopIds) !== JSON.stringify(newShopIds);

  // Problem: Keine Shops gefunden
  if (nearby.length === 0) {
    // Nur updaten wenn sich Status geändert hat
    const currentStatus = currentData?.property_zuordnungs_status || '';
    if (hasChanged || currentStatus !== '⚠️ Keine Shops') {
      results.push({
        json: {
          kandidat_name: k.name,
          kandidat_id: k.id,
          shop_ids: [],
          min_dist: null,
          status: '⚠️ Keine Shops',
          comment: `⚠️ Keine Fachgeschäfte in ${maxDist} km Umkreis gefunden.`
        }
      });
    }
  }
  // Erfolg: Shops gefunden
  else if (hasChanged) {
    const text = nearby.map((x,i) => `${i+1}. ${x.name}: ${x.dist} km`).join('\n');

    results.push({
      json: {
        kandidat_name: k.name,
        kandidat_id: k.id,
        shop_ids: nearby.map(x => x.id),
        min_dist: nearby[0].dist,
        status: '✅ OK',
        comment: 'Zugeordnete Geschäfte:\n' + text
      }
    });
  }
}

return results;
